INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das EVA-Prinzip nur für Computer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Menschen verarbeiten Daten so"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das EVA-Prinzip?', 3, '[{"text": "Datenverarbeitung strukturieren", "correct": true, "because": "Eingabe zu Ausgabe"}, {"text": "Daten speichern", "correct": false, "because": "Speicher separat"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst das EVA-Prinzip?', 5, '[{"text": "Eingabe", "correct": true, "because": "Datenaufnahme"}, {"text": "Verarbeitung", "correct": true, "because": "Datenbearbeitung"}, {"text": "Ausgabe", "correct": true, "because": "Ergebnisdarstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das EVA-Prinzip beschreibt Datenfluss. b) Es ist nur für Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim EVA-Prinzip?', 4, '[{"text": "Eingabegeräte", "correct": false, "because": "Datenaufnahme"}, {"text": "Verarbeitungsschritte", "correct": false, "because": "Datenbearbeitung"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das EVA-Prinzip Speicher enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Sonderstellung"}, {"text": "Ja", "correct": false, "because": "EVA(S) separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gerät ist für die Eingabe im EVA-Prinzip typisch?', 3, '[{"text": "Tastatur", "correct": true, "because": "Daten eingeben"}, {"text": "Monitor", "correct": false, "because": "Ausgabe"}, {"text": "Prozessor", "correct": false, "because": "Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das EVA-Prinzip?', 5, '[{"text": "Klarheit", "correct": true, "because": "Strukturierter Ablauf"}, {"text": "Universalität", "correct": true, "because": "Überall anwendbar"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das EVA-Prinzip gilt für alle Datenverarbeitung. b) Es ist nur für moderne Computer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch alte Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das EVA-Prinzip?', 4, '[{"text": "Eingabegerät", "correct": false, "because": "Datenaufnahme"}, {"text": "Verarbeitungseinheit", "correct": false, "because": "Datenbearbeitung"}, {"text": "Physisches Papier", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das EVA-Prinzip zeitlich festgelegt?', 2, '[{"text": "Ja", "correct": true, "because": "Reihenfolge wichtig"}, {"text": "Nein", "correct": false, "because": "Struktur vorgegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte sind im EVA-Prinzip beteiligt?', 4, '[{"text": "Maus", "correct": true, "because": "Eingabe"}, {"text": "Monitor", "correct": true, "because": "Ausgabe"}, {"text": "Stift", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das EVA-Prinzip nur für Software gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware"}, {"text": "Ja", "correct": false, "because": "Systemweit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim EVA-Prinzip?', 3, '[{"text": "Reihenfolge", "correct": true, "because": "E-V-A"}, {"text": "Farben", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das EVA-Prinzip ist universell. b) Es enthält Speicher als Hauptschritt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicher separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele zeigen das EVA-Prinzip?', 5, '[{"text": "Textverarbeitung", "correct": true, "because": "Eingabe über Tastatur"}, {"text": "Drucken", "correct": true, "because": "Ausgabe auf Papier"}, {"text": "Netzwerkdesign", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim EVA-Prinzip unwichtig?', 3, '[{"text": "Eingabe", "correct": false, "because": "Startpunkt"}, {"text": "Verarbeitung", "correct": false, "because": "Bearbeitung"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das EVA-Prinzip auch für Menschen gelten?', 3, '[{"text": "Ja", "correct": true, "because": "Z. B. hören, denken, sprechen"}, {"text": "Nein", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das EVA-Prinzip räumlich organisiert ist?', 2, '[{"text": "Ja", "correct": true, "because": "Geräte für E, V, A"}, {"text": "Nein", "correct": false, "because": "Auch räumlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für das EVA-Prinzip zentral?', 4, '[{"text": "Reihenfolge E-V-A", "correct": true, "because": "Grundstruktur"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung möglich"}]');
